css:
:where(.wtyg-map-site_indigenous_conflicts){--bg:#0d1117;--panel:#161b22;--line:#21262d;--ink:#e6edf3;--dim:#8b949e;--accent:#e5484d}
:where(.wtyg-map-site_indigenous_conflicts) *{box-sizing:border-box;margin:0;padding:0}
:where(.wtyg-map-site_indigenous_conflicts),:where(.wtyg-map-site_indigenous_conflicts){height:100%;font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,sans-serif;background:var(--bg);color:var(--ink)}
:where(.wtyg-map-site_indigenous_conflicts) :is([data-wtyg-id="app"],#wtyg-noid-app){display:flex;height:100vh;overflow:hidden}
:where(.wtyg-map-site_indigenous_conflicts) :is([data-wtyg-id="side"],#wtyg-noid-side){width:340px;flex-shrink:0;background:var(--panel);border-right:1px solid var(--line);display:flex;flex-direction:column;overflow:hidden}
:where(.wtyg-map-site_indigenous_conflicts) header{padding:18px 18px 14px;border-bottom:1px solid var(--line)}
:where(.wtyg-map-site_indigenous_conflicts) header h1{font-size:16px;font-weight:650;letter-spacing:-.2px;line-height:1.3}
:where(.wtyg-map-site_indigenous_conflicts) header p{font-size:12px;color:var(--dim);margin-top:5px}
:where(.wtyg-map-site_indigenous_conflicts) .stat{display:flex;gap:14px;padding:12px 18px;border-bottom:1px solid var(--line)}
:where(.wtyg-map-site_indigenous_conflicts) .stat div{flex:1}
:where(.wtyg-map-site_indigenous_conflicts) .stat b{font-size:22px;font-weight:700;color:var(--accent);display:block;font-variant-numeric:tabular-nums}
:where(.wtyg-map-site_indigenous_conflicts) .stat span{font-size:10.5px;color:var(--dim);text-transform:uppercase;letter-spacing:.5px}
:where(.wtyg-map-site_indigenous_conflicts) .ctrl{padding:14px 18px;border-bottom:1px solid var(--line)}
:where(.wtyg-map-site_indigenous_conflicts) .ctrl label{font-size:10.5px;text-transform:uppercase;letter-spacing:.5px;color:var(--dim);display:block;margin-bottom:6px}
:where(.wtyg-map-site_indigenous_conflicts) input,:where(.wtyg-map-site_indigenous_conflicts) select{width:100%;background:var(--bg);border:1px solid var(--line);color:var(--ink);padding:8px 10px;border-radius:7px;font-size:13px}
:where(.wtyg-map-site_indigenous_conflicts) input:focus,:where(.wtyg-map-site_indigenous_conflicts) select:focus{outline:none;border-color:var(--accent)}
:where(.wtyg-map-site_indigenous_conflicts) :is([data-wtyg-id="list"],#wtyg-noid-list){flex:1;overflow-y:auto}
:where(.wtyg-map-site_indigenous_conflicts) .item{padding:11px 18px;border-bottom:1px solid var(--line);cursor:pointer;transition:background .12s}
:where(.wtyg-map-site_indigenous_conflicts) .item:hover{background:#1c2230}
:where(.wtyg-map-site_indigenous_conflicts) .item h3{font-size:13px;font-weight:550;line-height:1.35}
:where(.wtyg-map-site_indigenous_conflicts) .item p{font-size:11px;color:var(--dim);margin-top:3px}
:where(.wtyg-map-site_indigenous_conflicts) .dot{display:inline-block;width:8px;height:8px;border-radius:50%;margin-right:6px;vertical-align:middle}
:where(.wtyg-map-site_indigenous_conflicts) :is([data-wtyg-id="map"],#wtyg-noid-map){flex:1}
:where(.wtyg-map-site_indigenous_conflicts) .legend{position:absolute;bottom:14px;left:14px;z-index:500;background:rgba(22,27,34,.94);border:1px solid var(--line);border-radius:9px;padding:10px 12px;font-size:11px;display:flex;flex-wrap:wrap;gap:4px 12px;max-width:520px}
:where(.wtyg-map-site_indigenous_conflicts) .lg{display:flex;align-items:center;gap:5px;color:var(--dim)}
:where(.wtyg-map-site_indigenous_conflicts) .lg i{width:9px;height:9px;border-radius:50%;display:inline-block}
:where(.wtyg-map-site_indigenous_conflicts) .leaflet-popup-content-wrapper{background:var(--panel);color:var(--ink);border-radius:10px}
:where(.wtyg-map-site_indigenous_conflicts) .leaflet-popup-tip{background:var(--panel)}
:where(.wtyg-map-site_indigenous_conflicts) .pop h3{font-size:14px;margin-bottom:6px;line-height:1.3;padding-right:6px}
:where(.wtyg-map-site_indigenous_conflicts) .pop .meta{font-size:12px;color:var(--dim);margin:2px 0}
:where(.wtyg-map-site_indigenous_conflicts) .pop .tag{display:inline-block;background:#21262d;padding:2px 8px;border-radius:5px;font-size:11px;margin:6px 4px 0 0}
:where(.wtyg-map-site_indigenous_conflicts) .pop .imp{margin-top:8px;font-size:11px;color:var(--dim);line-height:1.5}
:where(.wtyg-map-site_indigenous_conflicts) .pop a{color:var(--accent);font-size:12px;display:inline-block;margin-top:9px;text-decoration:none}
:where(.wtyg-map-site_indigenous_conflicts) .pop a:hover{text-decoration:underline}
:where(.wtyg-map-site_indigenous_conflicts) .acc{font-size:10px;color:#6e7681;margin-top:6px}
@media(max-width:720px){:where(.wtyg-map-site_indigenous_conflicts) :is([data-wtyg-id="side"],#wtyg-noid-side){position:absolute;z-index:1000;height:100%;transform:translateX(-100%);transition:.25s}
:where(.wtyg-map-site_indigenous_conflicts) :is([data-wtyg-id="side"],#wtyg-noid-side).open{transform:none}
:where(.wtyg-map-site_indigenous_conflicts) :is([data-wtyg-id="toggle"],#wtyg-noid-toggle){display:block}}
:where(.wtyg-map-site_indigenous_conflicts) :is([data-wtyg-id="toggle"],#wtyg-noid-toggle){display:none;position:absolute;top:12px;left:12px;z-index:1100;background:var(--accent);color:#fff;border:none;padding:9px 13px;border-radius:8px;font-size:13px;cursor:pointer}
